  constructor(readonly name: string) {}
}

class MiniContainer {
  readonly #factories = new Map<Token<unknown>, () => unknown>();
  readonly #singletons = new Map<Token<unknown>, unknown>();

  singleton<T>(token: Token<T>, factory: () => T): this {
    this.#factories.set(token, factory);
    return this;
  }

  resolve<T>(token: Token<T>): T {
    if (this.#singletons.has(token)) return this.#singletons.get(token) as T;
    const factory = this.#factories.get(token);
    if (!factory) throw new Error(`nothing registered for ${token.name}`);
    const instance = factory() as T;
    this.#singletons.set(token, instance);
    return instance;
  }
}

