class Token<T> {
  declare readonly __type: T;
  constructor(readonly name: string) {}
}

type Lifetime = "singleton" | "scoped";

class ScopedContainer {
  readonly #registrations = new Map<Token<unknown>, { lifetime: Lifetime; create: () => unknown }>();
  readonly #singletons = new Map<Token<unknown>, unknown>();

  register<T>(token: Token<T>, lifetime: Lifetime, create: () => T): this {
    this.#registrations.set(token, { lifetime, create });
    return this;
  }

  createScope(): { resolve<T>(token: Token<T>): T } {
    const scoped = new Map<Token<unknown>, unknown>();
    return {
      resolve: <T>(token: Token<T>): T => {
        const registration = this.#registrations.get(token);
        if (!registration) throw new Error(`nothing registered for ${token.name}`);
        const cache = registration.lifetime === "singleton" ? this.#singletons : scoped;
        if (!cache.has(token)) cache.set(token, registration.create());
        return cache.get(token) as T;
      },
    };
  }
}

