type Lifetime = "singleton" | "scoped" | "transient";

const lifetimes = new Map<string, Lifetime>([
  ["DailyReport", "singleton"],
  ["CheckoutService", "transient"],
  ["Cart", "scoped"],
  ["Clock", "singleton"],
]);

function checkCaptive(path: readonly string[]): string {
  const target = path.at(-1)!;
  if (lifetimes.get(target) !== "scoped") return "ok";
  const holder = path.slice(0, -1).find((name) => lifetimes.get(name) === "singleton");
  return holder ? `captive: ${holder} would keep ${target}` : "ok";
}

