function missingDependencies(graph: ReadonlyMap<string, readonly string[]>): string[] {
  const missing: string[] = [];
  for (const [service, deps] of graph) {
    for (const dep of deps) {
      if (!graph.has(dep)) missing.push(`${service} needs ${dep}`);
    }
  }
  return missing;
}

